-- Run in the application schema. Use this OR the Laravel migration, not both.
-- All timestamps are UTC. UUIDs are generated by the application.
CREATE TABLE chatbot_query_logs (
    id VARCHAR2(36) PRIMARY KEY,
    user_id NUMBER(19) NOT NULL,
    conversation_id VARCHAR2(36),
    scope VARCHAR2(32),
    cohort_id VARCHAR2(255),
    started_at TIMESTAMP NOT NULL,
    completed_at TIMESTAMP,
    duration_ms NUMBER(19),
    status VARCHAR2(24) NOT NULL,
    provider VARCHAR2(128),
    model VARCHAR2(255),
    question CLOB,
    answer CLOB,
    tools_json CLOB,
    llm_calls_json CLOB,
    feedback CLOB,
    input_tokens NUMBER(19),
    output_tokens NUMBER(19),
    total_tokens NUMBER(19),
    cache_read_tokens NUMBER(19),
    cache_write_tokens NUMBER(19),
    reasoning_tokens NUMBER(19),
    usage_status VARCHAR2(24) DEFAULT 'unavailable' NOT NULL,
    rating NUMBER(3),
    feedback_at TIMESTAMP,
    CONSTRAINT chatlog_rating_check CHECK (rating BETWEEN 1 AND 5)
);
CREATE INDEX chatlog_started_idx ON chatbot_query_logs (started_at);
CREATE INDEX chatlog_user_idx ON chatbot_query_logs (user_id, started_at);
CREATE INDEX chatlog_rating_idx ON chatbot_query_logs (rating, started_at);
CREATE INDEX chatlog_status_idx ON chatbot_query_logs (status, started_at);
